Looking at the task, I need to add a new handler that lists all invoices for a user. I'll follow the same pattern as the existing `get_invoice_handler`: call the service, format the response, and handle errors consistently.

The service already has a `list` method that returns invoices filtered by customer, sorted newest first. For each invoice, I need to fetch the total and format the fields as specified.

### invoicing/api.py
```python
from .errors import InvoiceError
from .money import format_inr


def _status(err):
    return {"NOT_FOUND": 404, "FORBIDDEN": 403}.get(err.code, 400)


def get_invoice_handler(service, invoice_id, user):
    """GET /invoices/{id}: returns (status, body)."""
    try:
        inv = service.get(invoice_id, user)
        total = service.total(invoice_id, user)
    except InvoiceError as e:
        return _status(e), {"error": e.code}
    return 200, {
        "id": inv.id,
        "customer": inv.customer,
        "created": inv.created.isoformat(),
        "total": total,
        "total_display": format_inr(total),
    }


def list_invoices_handler(service, user):
    """GET /invoices: returns (status, body) with list of invoices."""
    try:
        invoices = service.list(user)
        result = []
        for inv in invoices:
            total = service.total(inv.id, user)
            result.append({
                "id": inv.id,
                "created": inv.created.isoformat(),
                "total": total,
            })
    except InvoiceError as e:
        return _status(e), {"error": e.code}
    return 200, result
